import data from './licenses.json';

export interface LicenseEntry {
  name: string;
  version?: string;
  license: string;
  repository?: string;
  note?: string;
  /** Native (Android) library rather than an npm package. */
  native?: boolean;
  /** Index into `licenseTexts`, when the package ships a licence file. */
  text?: number;
}

/**
 * Open-source components that ship in the app (generated by `npm run licenses`, see
 * scripts/generate-licenses.mjs).
 */
export const licenses: readonly LicenseEntry[] = data.entries;
export const licenseTexts: readonly string[] = data.texts;
export const licensesGenerated: string = data.generated;
